			defaults.logger.error(`POST /__aimock/fixtures: invalid JSON: ${msg}`);
			res.writeHead(400, { "Content-Type": "application/json" });
			res.end(JSON.stringify({ error: `Invalid JSON: ${msg}` }));
			return true;
